CustomField.formula:
IF(
    AND(ISBLANK(Home_Sub_Score__c), ISBLANK(Away_Sub_Score__c)),
    /* Standard format: 3-1 */
    TEXT(Home_Score_Final__c) & " - " & TEXT(Away_Score_Final__c),
    /* AFL format: 10.8.68 - 9.12.66 or Cricket: 245/6 - 198/10 */
    TEXT(Home_Score_Final__c) & "." & TEXT(Home_Sub_Score__c) & " - " & TEXT(Away_Score_Final__c) & "." & TEXT(Away_Sub_Score__c)
)
